export function lockState(doc,layer){const state={all:false,position:false,pixels:false,transparency:false},seen=new Set();while(layer&&!seen.has(layer.id)){seen.add(layer.id);state.all||=!!layer.locked;for(const k of ['position','pixels','transparency'])state[k]||=!!layer.locks?.[k];layer=doc?.layers.find(l=>l.id===layer.parentId);}return state;}
export function canEdit(doc,l,op='appearance'){if(!l)return false;const s=lockState(doc,l);if(s.all)return false;if(['geometry','mask-geometry'].includes(op))return !s.position;if(op==='pixels')return !s.pixels;if(['replacepixels','erase'].includes(op))return !s.pixels&&!s.transparency;if(op==='destructive')return !s.position&&!s.pixels&&!s.transparency;return true;}
export function affectedLayers(d,list){const ids=new Set(list.map(l=>l.id));let changed=true;while(changed){changed=false;for(const l of d.layers)if(l.parentId&&ids.has(l.parentId)&&!ids.has(l.id)){ids.add(l.id);changed=true;}}return d.layers.filter(l=>ids.has(l.id));}
export function assertCanEdit(d,list,op='appearance',{descendants=false}={}){const blocked=(descendants?affectedLayers(d,list):list).find(l=>!canEdit(d,l,op));if(blocked)throw Error(`Lớp “${blocked.name}” đang khóa ${op==='geometry'?'vị trí':'nội dung'}. Mở khóa trước khi sửa.`);}
